"use client";
/* Gpu, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Gpu(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("gpu"); }, []);
  return React.createElement("piix-sprite", { "name": "gpu", ...piixAttrs(props) });
}

export default Gpu;
